seed.prefix.py:
def common_prefix(words):
    if not words:
        return ""
    first = words[0]
    second = words[1] if len(words) > 1 else words[0]
    n = 0
    while n < min(len(first), len(second)) and first[n] == second[n]:
        n += 1
    return first[:n]

